class Widget {};

// Factory function returns by value, relying on move semantics.
std::unique_ptr<Widget> createWidget() {
    return std::make_unique<Widget>();
}

void process() {
    // pw1 takes exclusive ownership of the new Widget.
    std::unique_ptr<Widget> pw1 = createWidget();

    // Ownership is transferred from pw1 to pw2. pw1 is now nullptr.
    std::unique_ptr<Widget> pw2 = std::move(pw1);

    // Error: unique_ptr is move-only, cannot be copied.
